import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from './BackButton';

interface Post {
  id: number;
  userId: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  postId: number;
  name: string;
  email: string;
  body: string;
}

interface PageProps {
  params: Promise<{
    id: string;
  }>;
}

// Generate static params (equivalent to getStaticPaths)
export async function generateStaticParams() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then(res => res.json());

  return posts.slice(0, 10).map((post: Post) => ({
    id: post.id.toString()
  }));
}

// Enable ISR with 5 minutes revalidation
export const revalidate = 300;

// Enable fallback for paths not generated at build time (equivalent to fallback: 'blocking')
export const dynamicParams = true;

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`).then(res => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`).then(res => res.json())
    ]);

    // Check if post exists
    if (!post || !post.id) {
      return null;
    }

    return { post, comments };
  } catch (error) {
    return null;
  }
}

// Generate metadata dynamically
export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params;
  const data = await getPostData(id);

  if (!data) {
    return {
      title: 'Post Not Found'
    };
  }

  return {
    title: data.post.title,
    description: data.post.body.substring(0, 160),
    openGraph: {
      title: data.post.title,
      description: data.post.body.substring(0, 160)
    }
  };
}

export default async function BlogPost({ params }: PageProps) {
  const { id } = await params;
  const data = await getPostData(id);

  if (!data) {
    notFound();
  }

  const { post, comments } = data;

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map(comment => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

